(() => {
  'use strict';
  const width=1080,height=1920,duration=51.5;
  const beats=[0,4.8,10.9,16.8,22.2,28,34,38.3,43,47,duration];
  const captions=['Cara set Private DNS','Apa fungsi DNS?','Cari “Private DNS”','Buka More connections','Pilih Manual','Cloudflare Security','Cloudflare Family','AdGuard DNS','Semak alamat DNS','Kembali ke Auto'];
  const ink='#10263b', muted='#39546a', copper='#a34022';
  const providers=[
    ['Cloudflare Security','security.cloudflare-dns.com','Tapis domain berkaitan malware','#9b501f'],
    ['Cloudflare Family','family.cloudflare-dns.com','Tapis malware dan kandungan dewasa','#66397a'],
    ['AdGuard DNS','dns.adguard-dns.com','Kurangkan iklan dan penjejak','#155278']
  ];
  const keys=['metal','panel','settings','connections','manual','confirmed','auto'];
  const assets={"metal":"","panel":"","settings":"","connections":"","manual":"","confirmed":"","auto":""};
  const images={};
  let readiness;
  async function load(key){
    const raw=atob(assets[key]);
    const bytes=Uint8Array.from(raw,char=>char.charCodeAt(0));
    const blob=new Blob([bytes],{type:'image/jpeg'});
    if(typeof createImageBitmap==='function'){
      images[key]=await createImageBitmap(blob);
      return;
    }
    const im=new Image(), url=URL.createObjectURL(blob);
    try{im.src=url;await im.decode();images[key]=im;}finally{URL.revokeObjectURL(url);}
  }
  function rect(c,x,y,w,h,r,fill){
    c.beginPath();c.roundRect(x,y,w,h,r);c.fillStyle=fill;c.fill();
  }
  function text(c,msg,x,y,size,color=ink,max=900,weight=750,mono=false){
    c.fillStyle=color;
    c.font=(weight>=700?'bold ':'')+size+'px '+(mono?'monospace':'Arial');
    c.textAlign='center';c.textBaseline='middle';c.fillText(msg,x,y,max);
  }
  function card(c,x,y,w,h,r=45){
    c.save();c.shadowColor='#17293666';c.shadowBlur=27;c.shadowOffsetY=15;
    rect(c,x,y,w,h,r,'#fffdf8');c.restore();
  }
  function screen(c,key,y,maxH){
    const im=images[key],scale=Math.min(700/im.width,maxH/im.height);
    const w=im.width*scale,h=im.height*scale,x=(1080-w)/2;
    card(c,x-8,y-8,w+16,h+16);
    c.save();c.beginPath();c.roundRect(x,y,w,h,32);c.clip();c.drawImage(im,x,y,w,h);c.restore();
    return {x,y,scale,w,h};
  }
  function pointer(c,x,y,t){
    const move=6*Math.sin(t*5.5);
    c.save();c.translate(x+move,y-move);c.rotate(-.76);
    c.beginPath();
    [[0,0],[38,-24],[38,-10],[102,-10],[102,10],[38,10],[38,24]].forEach(([a,b],i)=>i?c.lineTo(a,b):c.moveTo(a,b));
    c.closePath();c.lineJoin='round';c.lineWidth=7;c.strokeStyle='#fff8e7';c.stroke();
    c.fillStyle=copper;c.fill();c.restore();
  }
  function highlight(c,s,[a,b,d,e],t){
    const x=s.x+a*s.scale,y=s.y+b*s.scale,w=d*s.scale,h=e*s.scale;
    c.beginPath();c.roundRect(x,y,w,h,17);c.lineWidth=5;c.strokeStyle=copper;c.stroke();
    pointer(c,Math.min(x+w-7,844),y+h*.35,t);
  }
  function provider(c,p,y,large=false){
    const [name,host,benefit,tone]=p;
    const h=large?378:217;
    card(c,93,y,894,h,46);
    text(c,name,540,y+(large?87:47),large?55:45,tone,809);
    rect(c,122,y+(large?146:84),836,large?90:61,20,'#eaf0f5');
    text(c,host,540,y+(large?192:114),large?43:37,ink,798,750,true);
    text(c,benefit,540,y+(large?297:176),large?43:34,muted,806,650);
  }
  function routes(c){
    card(c,94,428,892,892,49);
    text(c,'Private DNS dalam Settings',540,504,49);
    const rows=[
      ['HONOR','More connections'],
      ['Samsung Galaxy','Connections → More connection settings'],
      ['Xiaomi 14T','More connectivity options'],
      ['Google Pixel','Network & internet'],
    ];
    rows.forEach(([brand,path],i)=>{
      const y=580+i*150;
      rect(c,142,y,796,134,28,['#f7e5d0','#eee7f5','#e6f0f9','#e9f2ef'][i]);
      text(c,brand,540,y+40,44);
      text(c,path,540,y+93,35,muted,750,650);
    });
    text(c,'Taip “Private DNS” dalam carian.',540,1246,37,muted,790,650);
  }
  function heading(c,index){
    rect(c,76,250,928,128,51,'#fffaf3f2');
    text(c,captions[index],540,315,72,ink,861,850);
    for(let i=0;i<10;i++)rect(c,290+i*52,395,38,8,4,i<=index?'#183852':'#fff6df');
  }
  function draw(c,t,w,h){
    c.save();c.scale(w/width,h/height);
    const time=Math.max(0,Math.min(t,duration-.001));
    let i=0;
    while(i<captions.length-1&&time>=beats[i+1])i++;
    const local=time-beats[i];
    c.fillStyle='#cbb48a';c.fillRect(0,0,width,height);
    if(images.metal)c.drawImage(images.metal,0,0,width,height);
    if(!images.manual){c.restore();return;}
    if(!this.hideLabels)heading(c,i);
    c.save();c.globalAlpha=Math.min(1,.80+local*2);
    const label=!this.hideLabels;
    if(i===0){
      const s=screen(c,'panel',466,817);
      if(label)highlight(c,s,[450,9,68,65],local);
      if(label)text(c,'Pada Android · Demo HONOR',540,1364,44);
    }else if(i===1){
      card(c,107,480,866,701,50);
      rect(c,169,561,742,217,35,'#e6eff6');
      text(c,'DNS',540,624,62,'#155278');
      text(c,'Cari alamat laman web',540,706,45);
      rect(c,169,834,742,234,35,'#f1e7f3');
      text(c,'Private DNS',540,908,58,'#66397a');
      text(c,'Sulitkan pertanyaan DNS',540,996,43);
    }else if(i===2){
      routes(c);
    }else if(i===3){
      const next=local>=2.32;
      const s=screen(c,next?'connections':'settings',428,1051);
      if(label)highlight(c,s,next?[15,900,542,74]:[15,881,542,74],local);
    }else if(i===4||i===5){
      const s=screen(c,'manual',431,861);
      const actual=providers[0][1];
      const n=i===5?actual.length:Math.floor(Math.max(0,Math.min(1,(local-2.45)/2.30))*actual.length);
      if(n){
        c.fillStyle='#182635';c.font='bold '+Math.round(23*s.scale)+'px Arial';
        c.textAlign='left';c.textBaseline='middle';
        c.fillText(actual.slice(0,n),s.x+44*s.scale,s.y+633*s.scale);
      }
      if(label)highlight(c,s,i===5||local>=2.45?[28,589,528,86]:[28,462,528,77],local);
      if(i===5&&label)provider(c,providers[0],1283);
    }else if(i===6||i===7){
      provider(c,providers[i-5],652,true);
    }else if(i===8){
      const s=screen(c,'confirmed',435,1051);
      if(label)highlight(c,s,[15,900,542,74],local);
    }else{
      const s=screen(c,'auto',494,800);
      if(label)highlight(c,s,[28,334,525,119],local);
    }
    c.restore();c.restore();
  }

  window.VIDEO={width,height,fps:30,duration,loop:false,beats,hideLabels:false,draw,
    ready(status){
      if(!readiness){
        status?.('Memuatkan paparan HONOR…');
        readiness=Promise.all(keys.map(load)).catch(error=>{readiness=null;throw error;});
      }
      return readiness;
    }
  };
})();
